#!/usr/bin/env python3
"""
Apply the parsimonious temporal-model extension for the joint sunspot GOF.

Safety properties:
- requires a clean Git tree;
- requires baseline commit 2496c437d5a6e92cd211103ebd0a0c9286a898a7;
- leaves the validated two-beta implementation untouched;
- creates only new R modules/spec/runner/tests;
- modifies only the C++ backend spec registry;
- never commits or pushes.
"""

from __future__ import annotations

import shutil
import subprocess
from pathlib import Path

EXPECTED_HEAD = "2496c437d5a6e92cd211103ebd0a0c9286a898a7"

NEW_FILES = {
    Path('real_data/sunspots/sunspots_cycle23_joint_time_models_parsimonious.R'): '#!/usr/bin/env Rscript\n\n# Parsimonious temporal laws for the joint cycle-23 sunspot model.\n#\n# This module deliberately leaves the validated two-beta implementation\n# untouched. It adds two separate temporal models:\n#   1. beta: a single Beta(alpha, beta) law;\n#   2. uniform_beta: (1 - lambda) Unif(0, 1) + lambda Beta(alpha, beta).\n\nresolve_sunspots_joint_parsimonious_path <- function(...) {\n  candidates <- c(\n    file.path(...),\n    file.path("..", ...),\n    file.path("..", "..", ...)\n  )\n  for (candidate in candidates) {\n    if (file.exists(candidate) || dir.exists(candidate)) return(candidate)\n  }\n  stop(sprintf("Could not resolve path: %s", file.path(...)))\n}\n\nif (!exists("prepare_sunspots_cycle23_joint_time_space_data", mode = "function")) {\n  source(resolve_sunspots_joint_parsimonious_path(\n    "real_data", "sunspots", "sunspots_cycle23_joint_time_space.R"\n  ))\n}\n\nnormalize_sunspots_joint_parsimonious_time_model <- function(\n    time_model = c("beta", "uniform_beta")) {\n  match.arg(time_model)\n}\n\nsunspots_joint_parsimonious_time_control <- function(control = list()) {\n  shape_lower <- as.numeric(\n    control$parsimonious_time_shape_lower %||% 1e-3\n  )\n  shape_upper <- as.numeric(\n    control$parsimonious_time_shape_upper %||% 1e3\n  )\n  weight_eps <- as.numeric(\n    control$parsimonious_time_weight_eps %||% 1e-4\n  )\n  boundary_tol <- as.numeric(\n    control$parsimonious_time_boundary_tol %||% 1e-5\n  )\n  uniform_identifiability_tol <- as.numeric(\n    control$parsimonious_uniform_identifiability_tol %||% 1e-3\n  )\n\n  if (length(shape_lower) != 1L ||\n      !is.finite(shape_lower) ||\n      shape_lower <= 0 ||\n      length(shape_upper) != 1L ||\n      !is.finite(shape_upper) ||\n      shape_upper <= shape_lower) {\n    stop("Parsimonious time-shape bounds must satisfy 0 < lower < upper.")\n  }\n  if (length(weight_eps) != 1L ||\n      !is.finite(weight_eps) ||\n      weight_eps <= 0 ||\n      weight_eps >= 0.5) {\n    stop("`parsimonious_time_weight_eps` must lie in (0, 0.5).")\n  }\n  if (length(boundary_tol) != 1L ||\n      !is.finite(boundary_tol) ||\n      boundary_tol < 0) {\n    stop("`parsimonious_time_boundary_tol` must be nonnegative.")\n  }\n  if (length(uniform_identifiability_tol) != 1L ||\n      !is.finite(uniform_identifiability_tol) ||\n      uniform_identifiability_tol < 0) {\n    stop("`parsimonious_uniform_identifiability_tol` must be nonnegative.")\n  }\n\n  list(\n    shape_lower = shape_lower,\n    shape_upper = shape_upper,\n    weight_eps = weight_eps,\n    boundary_tol = boundary_tol,\n    uniform_identifiability_tol = uniform_identifiability_tol\n  )\n}\n\nsunspots_joint_parsimonious_time_n_parameters <- function(time_model) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(time_model)\n  if (identical(time_model, "beta")) 2L else 3L\n}\n\nsunspots_joint_parsimonious_time_validate_eta <- function(\n    eta,\n    time_model = NULL,\n    control = list()) {\n  if (!is.list(eta)) stop("`eta` must be a list.")\n  if (is.null(time_model)) time_model <- eta$time_model\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(time_model)\n  bounds <- sunspots_joint_parsimonious_time_control(control)\n\n  required <- if (identical(time_model, "beta")) {\n    c("alpha", "beta")\n  } else {\n    c("beta_weight", "alpha", "beta")\n  }\n  if (!all(required %in% names(eta))) {\n    stop(sprintf(\n      "`eta` for time_model = \'%s\' must contain: %s.",\n      time_model,\n      paste(required, collapse = ", ")\n    ))\n  }\n\n  values <- vapply(eta[required], as.numeric, numeric(1L))\n  if (any(!is.finite(values))) {\n    stop("All parsimonious temporal parameters must be finite scalars.")\n  }\n  alpha <- values[["alpha"]]\n  beta <- values[["beta"]]\n  if (alpha < bounds$shape_lower || alpha > bounds$shape_upper ||\n      beta < bounds$shape_lower || beta > bounds$shape_upper) {\n    stop("Parsimonious time-shape parameters are outside their bounds.")\n  }\n\n  beta_weight <- if (identical(time_model, "beta")) {\n    1\n  } else {\n    values[["beta_weight"]]\n  }\n  if (identical(time_model, "uniform_beta") &&\n      (beta_weight < bounds$weight_eps ||\n       beta_weight > 1 - bounds$weight_eps)) {\n    stop("`beta_weight` is outside its admissible interval.")\n  }\n\n  list(\n    time_model = time_model,\n    beta_weight = beta_weight,\n    uniform_weight = 1 - beta_weight,\n    alpha = alpha,\n    beta = beta,\n    mean = alpha / (alpha + beta),\n    n_parameters = sunspots_joint_parsimonious_time_n_parameters(time_model)\n  )\n}\n\nsunspots_joint_parsimonious_time_pack_eta <- function(\n    eta,\n    time_model = NULL,\n    control = list()) {\n  eta <- sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n  if (identical(eta$time_model, "beta")) {\n    return(c(log(eta$alpha), log(eta$beta)))\n  }\n  c(\n    stats::qlogis(eta$beta_weight),\n    log(eta$alpha),\n    log(eta$beta)\n  )\n}\n\nsunspots_joint_parsimonious_time_unpack_eta <- function(\n    par,\n    time_model = c("beta", "uniform_beta"),\n    control = list()) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(time_model)\n  par <- as.numeric(par)\n  expected <- sunspots_joint_parsimonious_time_n_parameters(time_model)\n  if (length(par) != expected || any(!is.finite(par))) {\n    stop(sprintf(\n      "The \'%s\' temporal parameter vector must have %d finite entries.",\n      time_model, expected\n    ))\n  }\n\n  eta <- if (identical(time_model, "beta")) {\n    list(\n      time_model = time_model,\n      alpha = exp(par[[1L]]),\n      beta = exp(par[[2L]])\n    )\n  } else {\n    list(\n      time_model = time_model,\n      beta_weight = stats::plogis(par[[1L]]),\n      alpha = exp(par[[2L]]),\n      beta = exp(par[[3L]])\n    )\n  }\n  sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n}\n\nsunspots_joint_parsimonious_time_log_density <- function(\n    s,\n    eta,\n    time_model = NULL,\n    control = list()) {\n  s <- as.numeric(s)\n  if (any(!is.finite(s)) || any(s <= 0 | s >= 1)) {\n    stop("`s` must contain finite values in (0, 1).")\n  }\n  eta <- sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n  log_beta <- stats::dbeta(s, eta$alpha, eta$beta, log = TRUE)\n  if (identical(eta$time_model, "beta")) return(log_beta)\n\n  rotational_logsumexp2(\n    rep(log1p(-eta$beta_weight), length(s)),\n    log(eta$beta_weight) + log_beta\n  )\n}\n\nsunspots_joint_parsimonious_time_density <- function(\n    s,\n    eta,\n    time_model = NULL,\n    control = list()) {\n  exp(sunspots_joint_parsimonious_time_log_density(\n    s, eta, time_model = time_model, control = control\n  ))\n}\n\nsunspots_joint_parsimonious_time_cdf <- function(\n    s,\n    eta,\n    time_model = NULL,\n    control = list()) {\n  eta <- sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n  s <- as.numeric(s)\n  out <- numeric(length(s))\n  out[s >= 1] <- 1\n  active <- is.finite(s) & s > 0 & s < 1\n  beta_cdf <- stats::pbeta(s[active], eta$alpha, eta$beta)\n  out[active] <- if (identical(eta$time_model, "beta")) {\n    beta_cdf\n  } else {\n    eta$uniform_weight * s[active] + eta$beta_weight * beta_cdf\n  }\n  out[!is.finite(s) & s > 0] <- 1\n  pmin(pmax(out, 0), 1)\n}\n\nsunspots_joint_parsimonious_time_moment_match <- function(\n    s,\n    control = list()) {\n  bounds <- sunspots_joint_parsimonious_time_control(control)\n  s <- rotational_clamp_unit_interval(as.numeric(s), eps = 1e-10)\n  mean_s <- min(max(mean(s), 1e-6), 1 - 1e-6)\n  variance_s <- stats::var(s)\n  max_variance <- mean_s * (1 - mean_s) * (1 - 1e-8)\n  variance_s <- min(max(variance_s, 1e-8), max_variance)\n\n  raw_precision <- mean_s * (1 - mean_s) / variance_s - 1\n  precision_lower <- max(\n    bounds$shape_lower / mean_s,\n    bounds$shape_lower / (1 - mean_s)\n  )\n  precision_upper <- min(\n    bounds$shape_upper / mean_s,\n    bounds$shape_upper / (1 - mean_s)\n  )\n  precision <- min(max(raw_precision, precision_lower), precision_upper)\n\n  list(\n    alpha = mean_s * precision,\n    beta = (1 - mean_s) * precision\n  )\n}\n\nsunspots_joint_parsimonious_time_start_etas <- function(\n    s,\n    time_model = c("beta", "uniform_beta"),\n    control = list()) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(time_model)\n  base <- sunspots_joint_parsimonious_time_moment_match(s, control)\n  bounds <- sunspots_joint_parsimonious_time_control(control)\n  mean_s <- base$alpha / (base$alpha + base$beta)\n  precision <- base$alpha + base$beta\n\n  scaled_beta <- function(scale) {\n    candidate_precision <- precision * scale\n    candidate_precision <- min(\n      max(\n        candidate_precision,\n        bounds$shape_lower / mean_s,\n        bounds$shape_lower / (1 - mean_s)\n      ),\n      bounds$shape_upper / mean_s,\n      bounds$shape_upper / (1 - mean_s)\n    )\n    list(\n      alpha = mean_s * candidate_precision,\n      beta = (1 - mean_s) * candidate_precision\n    )\n  }\n\n  beta_candidates <- list(\n    base,\n    scaled_beta(0.5),\n    scaled_beta(2),\n    list(alpha = 1, beta = 1)\n  )\n  beta_candidates <- lapply(beta_candidates, function(candidate) {\n    sunspots_joint_parsimonious_time_validate_eta(\n      c(list(time_model = "beta"), candidate),\n      time_model = "beta",\n      control = control\n    )\n  })\n\n  if (identical(time_model, "beta")) return(beta_candidates)\n\n  weights <- c(0.2, 0.5, 0.8)\n  out <- list()\n  for (candidate in beta_candidates[seq_len(min(3L, length(beta_candidates)))]) {\n    for (weight in weights) {\n      out[[length(out) + 1L]] <-\n        sunspots_joint_parsimonious_time_validate_eta(\n          list(\n            time_model = "uniform_beta",\n            beta_weight = weight,\n            alpha = candidate$alpha,\n            beta = candidate$beta\n          ),\n          time_model = "uniform_beta",\n          control = control\n        )\n    }\n  }\n  out\n}\n\nsunspots_joint_parsimonious_time_select_fit <- function(\n    fits,\n    label = "parsimonious temporal") {\n  fits <- Filter(function(fit) {\n    !inherits(fit, "try-error") &&\n      is.list(fit) &&\n      length(fit$value) == 1L &&\n      is.finite(fit$value)\n  }, fits)\n  if (length(fits) == 0L) {\n    stop(sprintf("All %s optimizations failed.", label))\n  }\n\n  is_converged <- function(fit) {\n    convergence <- as.integer(fit$convergence %||% NA_integer_)\n    length(convergence) == 1L &&\n      !is.na(convergence) &&\n      convergence == 0L\n  }\n  converged <- Filter(is_converged, fits)\n  best <- fits[[which.min(vapply(fits, `[[`, numeric(1L), "value"))]]\n  selected_converged <- is_converged(best)\n  if (!selected_converged) {\n    warning(\n      sprintf(\n        "The selected %s optimization has convergence != 0; inspect the optimizer result.",\n        label\n      ),\n      call. = FALSE\n    )\n  }\n\n  list(\n    fit = best,\n    n_finite_fits = length(fits),\n    n_converged_fits = length(converged),\n    selected_converged = selected_converged\n  )\n}\n\nsunspots_joint_parsimonious_time_parameter_boundaries <- function(\n    eta,\n    time_model = NULL,\n    control = list()) {\n  eta <- sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n  bounds <- sunspots_joint_parsimonious_time_control(control)\n  tol <- bounds$boundary_tol\n\n  if (identical(eta$time_model, "beta")) {\n    parameter <- c("alpha", "beta")\n    value <- c(eta$alpha, eta$beta)\n    lower <- rep(bounds$shape_lower, 2L)\n    upper <- rep(bounds$shape_upper, 2L)\n  } else {\n    parameter <- c("beta_weight", "alpha", "beta")\n    value <- c(eta$beta_weight, eta$alpha, eta$beta)\n    lower <- c(bounds$weight_eps, rep(bounds$shape_lower, 2L))\n    upper <- c(1 - bounds$weight_eps, rep(bounds$shape_upper, 2L))\n  }\n\n  distance_lower <- value - lower\n  distance_upper <- upper - value\n  data.frame(\n    parameter = parameter,\n    value = value,\n    lower_bound = lower,\n    upper_bound = upper,\n    distance_to_lower = distance_lower,\n    distance_to_upper = distance_upper,\n    near_lower_bound = distance_lower <= tol,\n    near_upper_bound = distance_upper <= tol,\n    near_any_bound = distance_lower <= tol | distance_upper <= tol,\n    stringsAsFactors = FALSE\n  )\n}\n\nsunspots_joint_parsimonious_time_boundary_flags <- function(\n    eta,\n    time_model = NULL,\n    control = list()) {\n  eta <- sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n  diagnostics <- sunspots_joint_parsimonious_time_parameter_boundaries(\n    eta, time_model = eta$time_model, control = control\n  )\n  bounds <- sunspots_joint_parsimonious_time_control(control)\n  identification_distance <- if (identical(eta$time_model, "uniform_beta")) {\n    sqrt((eta$alpha - 1)^2 + (eta$beta - 1)^2)\n  } else {\n    NA_real_\n  }\n\n  list(\n    weight = if (identical(eta$time_model, "uniform_beta")) {\n      diagnostics$near_any_bound[\n        diagnostics$parameter == "beta_weight"\n      ]\n    } else {\n      FALSE\n    },\n    shape_lower = any(\n      diagnostics$near_lower_bound[\n        diagnostics$parameter %in% c("alpha", "beta")\n      ]\n    ),\n    shape_upper = any(\n      diagnostics$near_upper_bound[\n        diagnostics$parameter %in% c("alpha", "beta")\n      ]\n    ),\n    identification = identical(eta$time_model, "uniform_beta") &&\n      identification_distance <= bounds$uniform_identifiability_tol,\n    identification_distance = identification_distance\n  )\n}\n\nsunspots_joint_parsimonious_time_fast_regular <- function(\n    eta,\n    time_model = NULL,\n    control = list()) {\n  flags <- sunspots_joint_parsimonious_time_boundary_flags(\n    eta, time_model = time_model, control = control\n  )\n  !isTRUE(flags$weight) &&\n    !isTRUE(flags$shape_lower) &&\n    !isTRUE(flags$shape_upper) &&\n    !isTRUE(flags$identification)\n}\n\nfit_sunspots_joint_parsimonious_time <- function(\n    s,\n    time_model = c("beta", "uniform_beta"),\n    control = list()) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(time_model)\n  s <- as.numeric(s)\n  if (length(s) < 4L || any(!is.finite(s)) || any(s <= 0 | s >= 1)) {\n    stop("`s` must contain at least four finite values in (0, 1).")\n  }\n\n  starts <- sunspots_joint_parsimonious_time_start_etas(\n    s, time_model = time_model, control = control\n  )\n  n_starts <- as.integer(\n    control$parsimonious_time_n_starts %||% length(starts)\n  )\n  if (length(n_starts) != 1L ||\n      !is.finite(n_starts) ||\n      n_starts < 1L) {\n    stop("`parsimonious_time_n_starts` must be a positive integer.")\n  }\n  starts <- starts[seq_len(min(length(starts), n_starts))]\n\n  bounds <- sunspots_joint_parsimonious_time_control(control)\n  lower <- if (identical(time_model, "beta")) {\n    rep(log(bounds$shape_lower), 2L)\n  } else {\n    c(\n      stats::qlogis(bounds$weight_eps),\n      rep(log(bounds$shape_lower), 2L)\n    )\n  }\n  upper <- if (identical(time_model, "beta")) {\n    rep(log(bounds$shape_upper), 2L)\n  } else {\n    c(\n      stats::qlogis(1 - bounds$weight_eps),\n      rep(log(bounds$shape_upper), 2L)\n    )\n  }\n\n  objective <- function(par) {\n    value <- tryCatch({\n      eta <- sunspots_joint_parsimonious_time_unpack_eta(\n        par, time_model = time_model, control = control\n      )\n      -sum(sunspots_joint_parsimonious_time_log_density(\n        s, eta, time_model = time_model, control = control\n      ))\n    }, error = function(error) Inf)\n    if (is.finite(value)) value else .Machine$double.xmax / 100\n  }\n\n  nelder_mead_control <-\n    control$parsimonious_time_nelder_mead_control %||%\n    list(maxit = 3000L, reltol = 1e-10)\n  lbfgsb_control <-\n    control$parsimonious_time_optim_control %||%\n    list(maxit = 1500L, factr = 1e7, pgtol = 1e-8)\n\n  fits <- unlist(lapply(starts, function(start) {\n    par0 <- sunspots_joint_parsimonious_time_pack_eta(\n      start, time_model = time_model, control = control\n    )\n    par0 <- pmin(pmax(par0, lower), upper)\n    exploratory <- try(\n      stats::optim(\n        par0,\n        objective,\n        method = "Nelder-Mead",\n        control = nelder_mead_control\n      ),\n      silent = TRUE\n    )\n    candidates <- list(par0)\n    if (!inherits(exploratory, "try-error") &&\n        is.finite(exploratory$value)) {\n      candidates[[length(candidates) + 1L]] <-\n        pmin(pmax(exploratory$par, lower), upper)\n    }\n    lapply(candidates, function(candidate) {\n      try(\n        stats::optim(\n          candidate,\n          objective,\n          method = "L-BFGS-B",\n          lower = lower,\n          upper = upper,\n          control = lbfgsb_control\n        ),\n        silent = TRUE\n      )\n    })\n  }), recursive = FALSE)\n\n  selection <- sunspots_joint_parsimonious_time_select_fit(\n    fits,\n    label = sprintf("\'%s\' temporal", time_model)\n  )\n  best <- selection$fit\n  eta_hat <- sunspots_joint_parsimonious_time_unpack_eta(\n    best$par, time_model = time_model, control = control\n  )\n  boundary_diagnostics <-\n    sunspots_joint_parsimonious_time_parameter_boundaries(\n      eta_hat, time_model = time_model, control = control\n    )\n  boundary_flags <- sunspots_joint_parsimonious_time_boundary_flags(\n    eta_hat, time_model = time_model, control = control\n  )\n\n  if (!sunspots_joint_parsimonious_time_fast_regular(\n    eta_hat, time_model = time_model, control = control\n  )) {\n    warning(\n      sprintf(\n        paste(\n          "The \'%s\' temporal MLE is on a numerical boundary or is",\n          "not locally identified; the regular fast multiplier correction",\n          "must not be used."\n        ),\n        time_model\n      ),\n      call. = FALSE\n    )\n  }\n\n  c(eta_hat, list(\n    loglik = -best$value,\n    opt = best,\n    n_starts = length(starts),\n    n_successful_starts = selection$n_finite_fits,\n    n_converged_starts = selection$n_converged_fits,\n    selected_converged = selection$selected_converged,\n    boundary_flags = boundary_flags,\n    boundary_diagnostics = boundary_diagnostics,\n    fast_regular = sunspots_joint_parsimonious_time_fast_regular(\n      eta_hat, time_model = time_model, control = control\n    )\n  ))\n}\n\nsunspots_joint_parsimonious_time_score_matrix <- function(\n    s,\n    par,\n    time_model = c("beta", "uniform_beta"),\n    control = list()) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(time_model)\n  s <- as.numeric(s)\n  if (any(!is.finite(s)) || any(s <= 0 | s >= 1)) {\n    stop("`s` must contain finite values in (0, 1).")\n  }\n  eta <- sunspots_joint_parsimonious_time_unpack_eta(\n    par, time_model = time_model, control = control\n  )\n  score_alpha <- eta$alpha * (\n    log(s) -\n      digamma(eta$alpha) +\n      digamma(eta$alpha + eta$beta)\n  )\n  score_beta <- eta$beta * (\n    log1p(-s) -\n      digamma(eta$beta) +\n      digamma(eta$alpha + eta$beta)\n  )\n\n  if (identical(time_model, "beta")) {\n    return(cbind(score_alpha, score_beta))\n  }\n\n  log_beta <- stats::dbeta(s, eta$alpha, eta$beta, log = TRUE)\n  log_mix <- rotational_logsumexp2(\n    rep(log1p(-eta$beta_weight), length(s)),\n    log(eta$beta_weight) + log_beta\n  )\n  responsibility_beta <- exp(\n    log(eta$beta_weight) + log_beta - log_mix\n  )\n  cbind(\n    responsibility_beta - eta$beta_weight,\n    responsibility_beta * score_alpha,\n    responsibility_beta * score_beta\n  )\n}\n\nsample_sunspots_joint_parsimonious_time <- function(\n    n,\n    eta,\n    time_model = NULL,\n    control = list()) {\n  n <- as.integer(n)\n  if (length(n) != 1L || !is.finite(n) || n <= 0L) {\n    stop("`n` must be a positive integer.")\n  }\n  eta <- sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n  if (identical(eta$time_model, "beta")) {\n    out <- stats::rbeta(n, eta$alpha, eta$beta)\n  } else {\n    beta_component <- stats::runif(n) <= eta$beta_weight\n    out <- stats::runif(n)\n    out[beta_component] <- stats::rbeta(\n      sum(beta_component), eta$alpha, eta$beta\n    )\n  }\n  rotational_clamp_unit_interval(out, eps = .Machine$double.eps)\n}\n\nsunspots_joint_parsimonious_time_quadrature <- function(\n    eta,\n    n_nodes = 64L,\n    time_model = NULL,\n    control = list()) {\n  n_nodes <- as.integer(n_nodes)\n  if (length(n_nodes) != 1L ||\n      !is.finite(n_nodes) ||\n      n_nodes < 2L) {\n    stop("`n_nodes` must be an integer >= 2.")\n  }\n  eta <- sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n\n  beta_rule <- beta_mixture2_gauss_jacobi(\n    n_nodes,\n    alpha = eta$beta - 1,\n    beta = eta$alpha - 1\n  )\n  beta_nodes <- (beta_rule$nodes + 1) / 2\n  beta_weights <- beta_rule$weights / beta_rule$total_mass\n\n  if (identical(eta$time_model, "beta")) {\n    return(list(\n      nodes = beta_nodes,\n      weights = beta_weights,\n      n_nodes_per_component = n_nodes,\n      n_total_nodes = n_nodes,\n      mass_error = abs(sum(beta_weights) - 1)\n    ))\n  }\n\n  uniform_rule <- small_circle_gauss_legendre(n_nodes)\n  uniform_nodes <- (uniform_rule$nodes + 1) / 2\n  uniform_weights <- uniform_rule$weights / 2\n\n  nodes <- c(uniform_nodes, beta_nodes)\n  weights <- c(\n    eta$uniform_weight * uniform_weights,\n    eta$beta_weight * beta_weights\n  )\n  order_index <- order(nodes)\n  nodes <- nodes[order_index]\n  weights <- weights[order_index]\n\n  list(\n    nodes = nodes,\n    weights = weights,\n    n_nodes_per_component = n_nodes,\n    n_total_nodes = length(nodes),\n    mass_error = abs(sum(weights) - 1)\n  )\n}\n\nsunspots_joint_parsimonious_time_summary <- function(\n    eta,\n    time_model = NULL,\n    control = list()) {\n  eta <- sunspots_joint_parsimonious_time_validate_eta(\n    eta, time_model = time_model, control = control\n  )\n  flags <- sunspots_joint_parsimonious_time_boundary_flags(\n    eta, time_model = eta$time_model, control = control\n  )\n  list(\n    temporal_model = eta$time_model,\n    temporal_n_parameters = eta$n_parameters,\n    temporal_uniform_weight = eta$uniform_weight,\n    temporal_beta_weight = eta$beta_weight,\n    temporal_alpha = eta$alpha,\n    temporal_beta = eta$beta,\n    temporal_mean = eta$mean,\n    temporal_identification_distance =\n      flags$identification_distance,\n    temporal_boundary_weight = flags$weight,\n    temporal_boundary_shape_lower = flags$shape_lower,\n    temporal_boundary_shape_upper = flags$shape_upper,\n    temporal_identification_failure = flags$identification,\n    temporal_fast_regular =\n      sunspots_joint_parsimonious_time_fast_regular(\n        eta, time_model = eta$time_model, control = control\n      )\n  )\n}\n\nfit_sunspots_cycle23_joint_time_space_parsimonious <- function(\n    x,\n    s,\n    time_model = c("beta", "uniform_beta"),\n    hemisphere_regression = "shared",\n    control = list(),\n    eta_hat = NULL,\n    theta_hat = NULL) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(time_model)\n  data <- sunspots_joint_validate_data(x, s)\n\n  if (is.null(eta_hat)) {\n    eta_hat <- fit_sunspots_joint_parsimonious_time(\n      data$s, time_model = time_model, control = control\n    )\n  } else {\n    validated_eta <- sunspots_joint_parsimonious_time_validate_eta(\n      eta_hat, time_model = time_model, control = control\n    )\n    eta_hat <- c(\n      validated_eta,\n      eta_hat[setdiff(names(eta_hat), names(validated_eta))]\n    )\n  }\n  if (is.null(theta_hat)) {\n    theta_hat <- fit_sunspots_time_varying_asymmetric_mixture(\n      data$x,\n      data$s,\n      hemisphere_regression = hemisphere_regression,\n      control = control\n    )\n  }\n\n  temporal_loglik <- sum(\n    sunspots_joint_parsimonious_time_log_density(\n      data$s, eta_hat, time_model = time_model, control = control\n    )\n  )\n  conditional_loglik <- sunspots_time_varying_loglik(\n    data$x, data$s, theta_hat\n  )\n  n_parameters <- eta_hat$n_parameters + theta_hat$n_parameters\n  joint_loglik <- temporal_loglik + conditional_loglik\n\n  list(\n    time_model = time_model,\n    eta_hat = eta_hat,\n    theta_hat = theta_hat,\n    temporal_loglik = temporal_loglik,\n    conditional_loglik = conditional_loglik,\n    loglik = joint_loglik,\n    n_parameters = n_parameters,\n    aic = 2 * n_parameters - 2 * joint_loglik,\n    bic = n_parameters * log(nrow(data$x)) - 2 * joint_loglik\n  )\n}\n\nsunspots_joint_parsimonious_pack_par <- function(\n    fit,\n    control = list()) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(\n    fit$time_model %||% fit$eta_hat$time_model\n  )\n  c(\n    sunspots_joint_parsimonious_time_pack_eta(\n      fit$eta_hat, time_model = time_model, control = control\n    ),\n    sunspots_time_varying_pack_theta(\n      fit$theta_hat,\n      nu_eps = as.numeric(control$nu_eps %||% 1e-6),\n      c_min = as.numeric(control$c_min %||% 1e-8),\n      c_max = as.numeric(control$c_max %||% 1e6),\n      hemisphere_regression =\n        control$hemisphere_regression %||% "shared"\n    )\n  )\n}\n\nsunspots_joint_parsimonious_state_from_par <- function(\n    par,\n    control = list()) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(\n    control$time_model %||% "beta"\n  )\n  hemisphere_regression <-\n    sunspots_time_varying_normalize_hemisphere_regression(\n      control$hemisphere_regression %||% "shared"\n    )\n  temporal_length <-\n    sunspots_joint_parsimonious_time_n_parameters(time_model)\n  spatial_length <- if (identical(hemisphere_regression, "shared")) {\n    3L\n  } else {\n    5L\n  }\n  par <- as.numeric(par)\n  if (length(par) != temporal_length + spatial_length) {\n    stop("Joint parsimonious parameter vector has an incompatible length.")\n  }\n\n  temporal_indices <- seq_len(temporal_length)\n  spatial_indices <- temporal_length + seq_len(spatial_length)\n  list(\n    time_model = time_model,\n    eta = sunspots_joint_parsimonious_time_unpack_eta(\n      par[temporal_indices],\n      time_model = time_model,\n      control = control\n    ),\n    theta = sunspots_time_varying_unpack_par(\n      par[spatial_indices],\n      nu_eps = as.numeric(control$nu_eps %||% 1e-6),\n      c_min = as.numeric(control$c_min %||% 1e-8),\n      c_max = as.numeric(control$c_max %||% 1e6),\n      hemisphere_regression = hemisphere_regression\n    ),\n    eta_par = par[temporal_indices],\n    theta_par = par[spatial_indices]\n  )\n}\n\nsunspots_joint_parsimonious_score_matrix <- function(\n    data,\n    par,\n    control = list()) {\n  data <- sunspots_joint_validate_data(data$x, data$s)\n  state <- sunspots_joint_parsimonious_state_from_par(par, control)\n  cbind(\n    sunspots_joint_parsimonious_time_score_matrix(\n      data$s,\n      state$eta_par,\n      time_model = state$time_model,\n      control = control\n    ),\n    sunspots_time_gof_score_matrix(\n      list(x = data$x, u = data$s),\n      state$theta_par,\n      control\n    )\n  )\n}\n\nsample_sunspots_joint_time_space_parsimonious <- function(\n    n,\n    par,\n    control = list()) {\n  n <- as.integer(n)\n  if (length(n) != 1L || !is.finite(n) || n <= 0L) {\n    stop("`n` must be a positive integer.")\n  }\n  state <- sunspots_joint_parsimonious_state_from_par(par, control)\n  s <- sample_sunspots_joint_parsimonious_time(\n    n,\n    state$eta,\n    time_model = state$time_model,\n    control = control\n  )\n  nu <- sunspots_time_varying_nu(s, state$theta)\n  north <- stats::runif(n) <= 0.5\n  x <- matrix(0, nrow = n, ncol = 3L)\n  for (i in seq_len(n)) {\n    x[i, ] <- r_sph_small_circle(\n      n = 1L,\n      mu = if (north[[i]]) c(0, 0, 1) else c(0, 0, -1),\n      kappa = state$theta$c,\n      nu = if (north[[i]]) nu$north[[i]] else nu$south[[i]],\n      check = FALSE\n    )\n  }\n  list(x = x, s = s)\n}\n\nplot_sunspots_cycle23_joint_time_space_parsimonious_diagnostics <- function(\n    data,\n    fit,\n    output_dir,\n    control = list()) {\n  data <- sunspots_joint_validate_data(data$x, data$s)\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(\n    fit$time_model\n  )\n  s_grid <- seq(1e-5, 1 - 1e-5, length.out = 501L)\n\n  temporal_path <- file.path(\n    output_dir, "cycle23_joint_time_density_pit.png"\n  )\n  grDevices::png(\n    temporal_path, width = 1400, height = 700, res = 140\n  )\n  old_par <- par(mfrow = c(1, 2), mar = c(4, 4, 3, 1))\n  hist(\n    data$s,\n    breaks = 40,\n    freq = FALSE,\n    col = "#9ecae1",\n    border = "white",\n    xlab = "Dequantized first-record day",\n    main = sprintf("Temporal density: %s", time_model)\n  )\n  lines(\n    s_grid,\n    sunspots_joint_parsimonious_time_density(\n      s_grid,\n      fit$eta_hat,\n      time_model = time_model,\n      control = control\n    ),\n    col = "#8b0000",\n    lwd = 2\n  )\n  time_pit <- sunspots_joint_parsimonious_time_cdf(\n    data$s,\n    fit$eta_hat,\n    time_model = time_model,\n    control = control\n  )\n  qqplot(\n    stats::ppoints(length(time_pit)),\n    sort(time_pit),\n    xlim = c(0, 1),\n    ylim = c(0, 1),\n    pch = 16,\n    cex = 0.45,\n    col = "#2b6cb0",\n    xlab = "Uniform quantiles",\n    ylab = "Temporal PIT quantiles",\n    main = "Temporal PIT Q-Q plot"\n  )\n  abline(0, 1, col = "#8b0000", lwd = 2)\n  par(old_par)\n  grDevices::dev.off()\n\n  latitude_path <- file.path(\n    output_dir, "cycle23_joint_latitude_paths.png"\n  )\n  latitude <- asin(pmin(pmax(data$x[, 3L], -1), 1)) * 180 / pi\n  nu <- sunspots_time_varying_nu(s_grid, fit$theta_hat)\n  grDevices::png(\n    latitude_path, width = 1400, height = 900, res = 140\n  )\n  plot(\n    data$s,\n    latitude,\n    pch = 16,\n    cex = 0.35,\n    col = grDevices::adjustcolor(\n      ifelse(latitude >= 0, "#c43c39", "#2b6cb0"),\n      alpha.f = 0.22\n    ),\n    xlab = "Dequantized first-record day",\n    ylab = "Latitude (degrees)",\n    main = "Cycle 23: fitted north and south small-circle paths"\n  )\n  lines(\n    s_grid,\n    asin(nu$north) * 180 / pi,\n    col = "#8b0000",\n    lwd = 3\n  )\n  lines(\n    s_grid,\n    -asin(nu$south) * 180 / pi,\n    col = "#003f7f",\n    lwd = 3\n  )\n  grid(col = "#d9d9d9")\n  grDevices::dev.off()\n\n  axial_pit <- sunspots_time_varying_conditional_pit(\n    data$x[, 3L], data$s, fit$theta_hat\n  )\n  axial_path <- file.path(\n    output_dir, "cycle23_joint_conditional_axial_pit.png"\n  )\n  grDevices::png(\n    axial_path, width = 1400, height = 700, res = 140\n  )\n  old_par <- par(mfrow = c(1, 2), mar = c(4, 4, 3, 1))\n  hist(\n    axial_pit,\n    breaks = 20,\n    freq = FALSE,\n    col = "#9ecae1",\n    border = "white",\n    xlab = "Conditional axial PIT",\n    main = "Conditional axial PIT histogram",\n    xlim = c(0, 1)\n  )\n  abline(h = 1, col = "#8b0000", lwd = 2)\n  qqplot(\n    stats::ppoints(length(axial_pit)),\n    sort(axial_pit),\n    xlim = c(0, 1),\n    ylim = c(0, 1),\n    pch = 16,\n    cex = 0.45,\n    col = "#2b6cb0",\n    xlab = "Uniform quantiles",\n    ylab = "Conditional PIT quantiles",\n    main = "Conditional axial PIT Q-Q plot"\n  )\n  abline(0, 1, col = "#8b0000", lwd = 2)\n  par(old_par)\n  grDevices::dev.off()\n\n  list(\n    temporal_path = temporal_path,\n    latitude_path = latitude_path,\n    axial_path = axial_path,\n    time_pit = time_pit,\n    axial_pit = axial_pit\n  )\n}\n',
    Path('bootstrap/sunspots_joint_time_space_parsimonious_model_spec.R'): '# Parsimonious temporal-model adapter for the joint sunspot GOF tests.\n\nresolve_sunspots_joint_parsimonious_spec_path <- function(...) {\n  candidates <- c(\n    file.path(...),\n    file.path("..", ...),\n    file.path("..", "..", ...)\n  )\n  for (candidate in candidates) {\n    if (file.exists(candidate) || dir.exists(candidate)) return(candidate)\n  }\n  stop(sprintf("Could not resolve path: %s", file.path(...)))\n}\n\nif (!exists("make_sunspots_joint_time_space_spec", mode = "function")) {\n  source(resolve_sunspots_joint_parsimonious_spec_path(\n    "bootstrap", "sunspots_joint_time_space_model_spec.R"\n  ))\n}\nif (!exists(\n  "fit_sunspots_cycle23_joint_time_space_parsimonious",\n  mode = "function"\n)) {\n  source(resolve_sunspots_joint_parsimonious_spec_path(\n    "real_data",\n    "sunspots",\n    "sunspots_cycle23_joint_time_models_parsimonious.R"\n  ))\n}\n\nrequire_sunspots_joint_parsimonious_spec_dependencies <- function() {\n  required <- c(\n    "normalize_sunspots_joint_spec_data",\n    "sunspots_joint_spec_distance_matrix",\n    "sunspots_joint_profile_block",\n    "sunspots_joint_profile_block_sorted",\n    "sunspots_joint_conditional_legendre_coefficients",\n    "fit_sunspots_cycle23_joint_time_space_parsimonious",\n    "sunspots_joint_parsimonious_time_quadrature",\n    "sunspots_joint_parsimonious_pack_par",\n    "sunspots_joint_parsimonious_score_matrix",\n    "sample_sunspots_joint_time_space_parsimonious"\n  )\n  missing <- required[\n    !vapply(required, exists, logical(1L), mode = "function")\n  ]\n  if (length(missing) > 0L) {\n    stop(sprintf(\n      "Missing parsimonious joint-model dependencies: %s.",\n      paste(missing, collapse = ", ")\n    ))\n  }\n  invisible(TRUE)\n}\n\nfit_sunspots_joint_parsimonious_spec_theta <- function(\n    data,\n    weights = NULL,\n    null,\n    control = list()) {\n  require_sunspots_joint_parsimonious_spec_dependencies()\n  normalized <- normalize_sunspots_joint_spec_data(data, control)\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(\n    control$time_model %||% "beta"\n  )\n  hemisphere_regression <-\n    sunspots_time_varying_normalize_hemisphere_regression(\n      control$hemisphere_regression %||% "shared"\n    )\n\n  if (!is.list(null) || is.null(null$type)) {\n    stop("`null` must be a list containing at least `type`.")\n  }\n  if (identical(null$type, "simple")) {\n    theta_simple <- null$theta\n    if (!is.list(theta_simple) ||\n        is.null(theta_simple$eta_hat) ||\n        is.null(theta_simple$theta_hat)) {\n      stop(\n        "For a simple null, `null$theta` must contain `eta_hat` and `theta_hat`."\n      )\n    }\n    return(fit_sunspots_cycle23_joint_time_space_parsimonious(\n      x = normalized$x,\n      s = normalized$s,\n      time_model = time_model,\n      hemisphere_regression = hemisphere_regression,\n      control = control,\n      eta_hat = theta_simple$eta_hat,\n      theta_hat = theta_simple$theta_hat\n    ))\n  }\n  if (!identical(null$type, "composite")) {\n    stop("`null$type` must be either `simple` or `composite`.")\n  }\n  if (!is.null(weights)) {\n    stop(\n      paste(\n        "The parsimonious joint sunspot specs only support",\n        "`bootstrap_method = \'fast_multiplier\'`;",\n        "weighted refits are not implemented."\n      )\n    )\n  }\n\n  fit_sunspots_cycle23_joint_time_space_parsimonious(\n    x = normalized$x,\n    s = normalized$s,\n    time_model = time_model,\n    hemisphere_regression = hemisphere_regression,\n    control = control\n  )\n}\n\nsunspots_joint_parsimonious_spec_profile_eval <- function(\n    omega,\n    t,\n    theta,\n    control = list()) {\n  require_sunspots_joint_parsimonious_spec_dependencies()\n  omega <- as.numeric(omega)\n  if (length(omega) != 4L || any(!is.finite(omega))) {\n    stop("`omega` must be a finite vector (x1, x2, x3, s).")\n  }\n  center <- sunspots_joint_validate_data(\n    x = matrix(omega[1:3], nrow = 1L),\n    s = omega[[4L]]\n  )\n  fit <- theta\n  if (!is.list(fit) ||\n      is.null(fit$eta_hat) ||\n      is.null(fit$theta_hat) ||\n      is.null(fit$time_model)) {\n    stop(\n      "`theta` must be a fitted parsimonious joint object."\n    )\n  }\n\n  quadrature <- sunspots_joint_parsimonious_time_quadrature(\n    fit$eta_hat,\n    n_nodes = as.integer(control$time_quad_n %||% 64L),\n    time_model = fit$time_model,\n    control = control\n  )\n  coefficients <- sunspots_joint_conditional_legendre_coefficients(\n    fit$theta_hat,\n    quadrature$nodes,\n    l_max = as.integer(control$profile_l_max %||% 100L),\n    quad_n = as.integer(control$profile_quad_n %||% 400L)\n  )\n\n  as.numeric(sunspots_joint_profile_block(\n    radii = matrix(as.numeric(t), nrow = 1L),\n    rho = center$x[1L, 3L],\n    center_s = center$s,\n    time_nodes = quadrature$nodes,\n    time_weights = quadrature$weights,\n    coefficients = coefficients,\n    backend = control$distance_profile_backend %||% "auto"\n  ))\n}\n\nsunspots_joint_parsimonious_spec_sorted_prepare <- function(\n    data,\n    sorted_distance_matrix,\n    theta,\n    control = list()) {\n  require_sunspots_joint_parsimonious_spec_dependencies()\n  normalized <- normalize_sunspots_joint_spec_data(data, control)\n  fit <- theta\n  if (!is.list(fit) ||\n      is.null(fit$eta_hat) ||\n      is.null(fit$theta_hat) ||\n      is.null(fit$time_model)) {\n    stop("`theta` must be a fitted parsimonious joint object.")\n  }\n\n  sorted_distance_matrix <- as.matrix(sorted_distance_matrix)\n  n <- nrow(normalized$x)\n  if (!identical(dim(sorted_distance_matrix), c(n, n))) {\n    stop(\n      "`sorted_distance_matrix` has incompatible dimensions."\n    )\n  }\n\n  quadrature <- sunspots_joint_parsimonious_time_quadrature(\n    fit$eta_hat,\n    n_nodes = as.integer(control$time_quad_n %||% 64L),\n    time_model = fit$time_model,\n    control = control\n  )\n  coefficients <- sunspots_joint_conditional_legendre_coefficients(\n    fit$theta_hat,\n    quadrature$nodes,\n    l_max = as.integer(control$profile_l_max %||% 100L),\n    quad_n = as.integer(control$profile_quad_n %||% 400L)\n  )\n  backend <- sunspots_joint_effective_backend(\n    control$distance_profile_backend %||% "r"\n  )\n  if (identical(backend, "cpp")) ensure_distance_profile_cpp_loaded()\n\n  list(\n    n = n,\n    rho = as.numeric(normalized$x[, 3L]),\n    center_s = as.numeric(normalized$s),\n    time_nodes = quadrature$nodes,\n    time_weights = quadrature$weights,\n    coefficients = coefficients,\n    backend = backend\n  )\n}\n\nsunspots_joint_parsimonious_spec_sorted_block_eval <- function(\n    data,\n    sorted_distance_matrix,\n    theta,\n    row_indices,\n    prepared = NULL,\n    control = list()) {\n  sorted_distance_matrix <- as.matrix(sorted_distance_matrix)\n  n <- nrow(sorted_distance_matrix)\n  if (ncol(sorted_distance_matrix) != n) {\n    stop("`sorted_distance_matrix` must be square.")\n  }\n  row_indices <- as.integer(row_indices)\n  if (length(row_indices) == 0L ||\n      any(!is.finite(row_indices)) ||\n      any(row_indices < 1L | row_indices > n)) {\n    stop("`row_indices` contains invalid sample indices.")\n  }\n  if (is.null(prepared)) {\n    prepared <- sunspots_joint_parsimonious_spec_sorted_prepare(\n      data = data,\n      sorted_distance_matrix = sorted_distance_matrix,\n      theta = theta,\n      control = control\n    )\n  }\n  if (!is.list(prepared) ||\n      !identical(as.integer(prepared$n), as.integer(n)) ||\n      length(prepared$rho) != n ||\n      length(prepared$center_s) != n) {\n    stop("The prepared parsimonious profile context is incompatible.")\n  }\n\n  values <- sunspots_joint_profile_block_sorted(\n    radii = sorted_distance_matrix[row_indices, , drop = FALSE],\n    rho = prepared$rho[row_indices],\n    center_s = prepared$center_s[row_indices],\n    time_nodes = prepared$time_nodes,\n    time_weights = prepared$time_weights,\n    coefficients = prepared$coefficients,\n    backend = prepared$backend\n  )\n  matrix(\n    as.numeric(values),\n    nrow = length(row_indices),\n    ncol = n\n  )\n}\n\nsunspots_joint_parsimonious_spec_profile_matrix_eval <- function(\n    data,\n    distance_matrix,\n    theta,\n    control = list()) {\n  prepared <- sunspots_joint_parsimonious_spec_sorted_prepare(\n    data = data,\n    sorted_distance_matrix = distance_matrix,\n    theta = theta,\n    control = control\n  )\n  block_size <- as.integer(control$center_block_size %||% 8L)\n  if (length(block_size) != 1L ||\n      !is.finite(block_size) ||\n      block_size <= 0L) {\n    stop("`control$center_block_size` must be positive.")\n  }\n\n  n <- prepared$n\n  out <- matrix(0, nrow = n, ncol = n)\n  for (block_start in seq.int(1L, n, by = block_size)) {\n    block_end <- min(block_start + block_size - 1L, n)\n    row_indices <- block_start:block_end\n    out[row_indices, ] <- sunspots_joint_profile_block(\n      radii = distance_matrix[row_indices, , drop = FALSE],\n      rho = prepared$rho[row_indices],\n      center_s = prepared$center_s[row_indices],\n      time_nodes = prepared$time_nodes,\n      time_weights = prepared$time_weights,\n      coefficients = prepared$coefficients,\n      backend = prepared$backend\n    )\n  }\n  out\n}\n\nprepare_sunspots_joint_parsimonious_fast_multiplier <- function(\n    spec,\n    data,\n    theta_hat,\n    ks_prep = NULL,\n    cvm_prep = NULL,\n    control = list()) {\n  require_sunspots_joint_parsimonious_spec_dependencies()\n  normalized <- normalize_sunspots_joint_spec_data(data, control)\n  if (!is.list(theta_hat) ||\n      is.null(theta_hat$eta_hat) ||\n      is.null(theta_hat$theta_hat) ||\n      is.null(theta_hat$time_model)) {\n    stop("`theta_hat` must be a fitted parsimonious joint object.")\n  }\n  if (!sunspots_joint_parsimonious_time_fast_regular(\n    theta_hat$eta_hat,\n    time_model = theta_hat$time_model,\n    control = control\n  )) {\n    stop(\n      paste(\n        "The parsimonious temporal MLE is on a boundary or is not",\n        "locally identified; fast multiplier preparation is invalid."\n      ),\n      call. = FALSE\n    )\n  }\n\n  par0 <- sunspots_joint_parsimonious_pack_par(\n    theta_hat, control = control\n  )\n  prepare_fast_multiplier_score_model(\n    spec = spec,\n    data = normalized,\n    theta_hat = theta_hat,\n    ks_prep = ks_prep,\n    cvm_prep = cvm_prep,\n    control = control,\n    par0 = par0,\n    score_matrix_fn = function(sample, par) {\n      sunspots_joint_parsimonious_score_matrix(\n        sample, par, control = control\n      )\n    },\n    sample_fn = function(n_aux, par) {\n      sample_sunspots_joint_time_space_parsimonious(\n        n_aux, par, control = control\n      )\n    }\n  )\n}\n\nmake_sunspots_joint_time_space_parsimonious_spec <- function(\n    time_model = c("beta", "uniform_beta"),\n    hemisphere_regression = c("shared", "asymmetric")) {\n  time_model <- normalize_sunspots_joint_parsimonious_time_model(\n    time_model\n  )\n  hemisphere_regression <-\n    sunspots_time_varying_normalize_hemisphere_regression(\n      match.arg(hemisphere_regression)\n    )\n  spec_name <- sprintf(\n    "sunspots_joint_time_space_%s_%s",\n    time_model,\n    hemisphere_regression\n  )\n\n  add_control <- function(control) {\n    utils::modifyList(control, list(\n      time_model = time_model,\n      hemisphere_regression = hemisphere_regression\n    ))\n  }\n\n  new_model_spec(\n    name = spec_name,\n    fit_theta = function(\n        data,\n        weights = NULL,\n        null,\n        control = list()) {\n      fit_sunspots_joint_parsimonious_spec_theta(\n        data = data,\n        weights = weights,\n        null = null,\n        control = add_control(control)\n      )\n    },\n    distance_matrix = function(data, omega, control = list()) {\n      sunspots_joint_spec_distance_matrix(\n        data, omega, control = add_control(control)\n      )\n    },\n    profile_eval = function(omega, t, theta, control = list()) {\n      sunspots_joint_parsimonious_spec_profile_eval(\n        omega, t, theta, control = add_control(control)\n      )\n    },\n    normalize_data = function(data, control = list()) {\n      normalize_sunspots_joint_spec_data(\n        data, control = add_control(control)\n      )\n    },\n    n_obs = function(data, control = list()) {\n      normalized <- normalize_sunspots_joint_spec_data(\n        data, add_control(control)\n      )\n      nrow(normalized$x)\n    },\n    observation_at = function(data, idx, control = list()) {\n      normalized <- normalize_sunspots_joint_spec_data(\n        data, add_control(control)\n      )\n      sunspots_joint_spec_obs_row(normalized, idx)\n    },\n    extras = list(\n      sample_profile_matrix_eval = function(\n          data,\n          distance_matrix,\n          theta,\n          control = list()) {\n        sunspots_joint_parsimonious_spec_profile_matrix_eval(\n          data,\n          distance_matrix,\n          theta,\n          control = add_control(control)\n        )\n      },\n      sample_profile_sorted_prepare = function(\n          data,\n          sorted_distance_matrix,\n          theta,\n          control = list()) {\n        sunspots_joint_parsimonious_spec_sorted_prepare(\n          data,\n          sorted_distance_matrix,\n          theta,\n          control = add_control(control)\n        )\n      },\n      sample_profile_sorted_block_eval = function(\n          data,\n          sorted_distance_matrix,\n          theta,\n          row_indices,\n          prepared = NULL,\n          control = list()) {\n        sunspots_joint_parsimonious_spec_sorted_block_eval(\n          data,\n          sorted_distance_matrix,\n          theta,\n          row_indices,\n          prepared = prepared,\n          control = add_control(control)\n        )\n      },\n      fast_multiplier_prepare = function(\n          data,\n          theta_hat,\n          ks_prep = NULL,\n          cvm_prep = NULL,\n          control = list()) {\n        control <- add_control(control)\n        prepare_sunspots_joint_parsimonious_fast_multiplier(\n          spec = make_sunspots_joint_time_space_parsimonious_spec(\n            time_model = time_model,\n            hemisphere_regression = hemisphere_regression\n          ),\n          data = data,\n          theta_hat = theta_hat,\n          ks_prep = ks_prep,\n          cvm_prep = cvm_prep,\n          control = control\n        )\n      },\n      weighted_mle = FALSE\n    )\n  )\n}\n',
    Path('real_data/sunspots/run_sunspots_cycle23_joint_time_space_parsimonious_gof.R'): '#!/usr/bin/env Rscript\n\n# Joint cycle-23 sunspot GOF runner for parsimonious temporal models:\n#   beta and uniform_beta.\n#\n# The validated two-beta runner remains unchanged.\n\nresolve_sunspots_joint_parsimonious_runner_path <- function(...) {\n  candidates <- c(\n    file.path(...),\n    file.path("..", ...),\n    file.path("..", "..", ...)\n  )\n  for (candidate in candidates) {\n    if (file.exists(candidate) || dir.exists(candidate)) return(candidate)\n  }\n  stop(sprintf("Could not resolve path: %s", file.path(...)))\n}\n\nsource(resolve_sunspots_joint_parsimonious_runner_path(\n  "real_data", "sunspots", "sunspots_cycle23_joint_time_space.R"\n))\nsource(resolve_sunspots_joint_parsimonious_runner_path(\n  "real_data",\n  "sunspots",\n  "sunspots_cycle23_joint_time_models_parsimonious.R"\n))\nsource(resolve_sunspots_joint_parsimonious_runner_path(\n  "bootstrap", "sunspots_joint_time_space_parsimonious_model_spec.R"\n))\nsource(resolve_sunspots_joint_parsimonious_runner_path(\n  "bootstrap", "multiplier_bootstrap.R"\n))\n\nsunspots_joint_parsimonious_parse_statistics <- function(statistics) {\n  normalize_requested_statistics(statistics)\n}\n\nsunspots_joint_parsimonious_model_label <- function(\n    time_model,\n    hemisphere_regression) {\n  sprintf(\n    "joint_time_space_%s_small_circle_%s",\n    hemisphere_regression,\n    time_model\n  )\n}\n\nsunspots_joint_parsimonious_summary_row <- function(\n    statistic_name,\n    bootstrap_values,\n    observed_value,\n    fit,\n    generic_result,\n    data,\n    center_indices,\n    settings,\n    timing,\n    numerical_diagnostics,\n    control = list()) {\n  eta <- fit$eta_hat\n  theta <- fit$theta_hat\n  temporal <- sunspots_joint_parsimonious_time_summary(\n    eta,\n    time_model = fit$time_model,\n    control = control\n  )\n\n  legacy_weight1 <- if (identical(fit$time_model, "beta")) {\n    1\n  } else {\n    eta$beta_weight\n  }\n\n  data.frame(\n    model = sunspots_joint_parsimonious_model_label(\n      fit$time_model, settings$hemisphere_regression\n    ),\n    temporal_model = temporal$temporal_model,\n    hemisphere_regression = settings$hemisphere_regression,\n    n_parameters = fit$n_parameters,\n    temporal_n_parameters = temporal$temporal_n_parameters,\n    statistic_type = if (identical(statistic_name, "ks")) {\n      "ks_sample_centers_product_metric"\n    } else {\n      "cvm_sample_centers_product_metric"\n    },\n    bootstrap_method = "fast_multiplier_joint_time_space",\n    profile_scope = "joint_time_space_product_law",\n    product_metric =\n      "0.5 * (geodesic/pi + absolute_time_difference)",\n    n = nrow(data$x),\n    n_sample_centers = length(center_indices),\n    B = settings$B,\n    derivative_mc_size =\n      generic_result$diagnostics$derivative_mc_size,\n    n_cores = settings$n_cores,\n    observed_profile_n_cores =\n      settings$observed_profile_n_cores,\n    start_date = settings$start_date,\n    end_date_exclusive = settings$end_date,\n    center_seed = settings$center_seed,\n    dequantization_seed = settings$dequantization_seed,\n    derivative_mc_seed = settings$derivative_mc_seed,\n    bootstrap_seed = settings$bootstrap_seed,\n    time_quad_n_per_component = settings$time_quad_n,\n    profile_l_max = settings$profile_l_max,\n    spatial_quad_n = settings$spatial_quad_n,\n    distance_profile_backend =\n      settings$distance_profile_backend,\n    statistic = observed_value,\n    critical_value_0.95 = as.numeric(stats::quantile(\n      bootstrap_values,\n      probs = 0.95,\n      names = FALSE,\n      type = 8\n    )),\n    p_value =\n      (1 + sum(bootstrap_values >= observed_value)) /\n      (length(bootstrap_values) + 1),\n    temporal_uniform_weight =\n      temporal$temporal_uniform_weight,\n    temporal_beta_weight =\n      temporal$temporal_beta_weight,\n    temporal_alpha = temporal$temporal_alpha,\n    temporal_beta = temporal$temporal_beta,\n    temporal_mean = temporal$temporal_mean,\n    temporal_identification_distance =\n      temporal$temporal_identification_distance,\n    temporal_weight1 = legacy_weight1,\n    temporal_alpha1 = eta$alpha,\n    temporal_beta1 = eta$beta,\n    temporal_alpha2 = NA_real_,\n    temporal_beta2 = NA_real_,\n    temporal_mean1 = eta$mean,\n    temporal_mean2 = NA_real_,\n    temporal_loglik = fit$temporal_loglik,\n    conditional_loglik = fit$conditional_loglik,\n    joint_loglik = fit$loglik,\n    aic = fit$aic,\n    bic = fit$bic,\n    a_N = theta$a_N,\n    b_N = theta$b_N,\n    a_S = theta$a_S,\n    b_S = theta$b_S,\n    c = theta$c,\n    temporal_convergence = eta$opt$convergence,\n    spatial_convergence = theta$opt$convergence,\n    temporal_boundary_weight =\n      temporal$temporal_boundary_weight,\n    temporal_boundary_shape_lower =\n      temporal$temporal_boundary_shape_lower,\n    temporal_boundary_shape_upper =\n      temporal$temporal_boundary_shape_upper,\n    temporal_identification_failure =\n      temporal$temporal_identification_failure,\n    temporal_fast_regular =\n      temporal$temporal_fast_regular,\n    vhat_rcond =\n      generic_result$diagnostics$Vhat_rcond,\n    vhat_condition_number =\n      generic_result$diagnostics$Vhat_condition_number,\n    vhat_min_positive_eigenvalue =\n      numerical_diagnostics$Vhat_min_positive_eigenvalue,\n    vhat_max_positive_eigenvalue =\n      numerical_diagnostics$Vhat_max_positive_eigenvalue,\n    vhat_inversion_method = "solve",\n    vhat_regularization_added = 0,\n    correction_all_finite = TRUE,\n    temporal_mle_seconds = timing$temporal_mle_seconds,\n    spatial_mle_seconds = timing$spatial_mle_seconds,\n    observed_profile_seconds =\n      timing$observed_profile_seconds,\n    fast_preparation_seconds =\n      timing$fast_preparation_seconds,\n    bootstrap_seconds = timing$bootstrap_seconds,\n    total_seconds = timing$total_seconds,\n    stringsAsFactors = FALSE\n  )\n}\n\nrun_sunspots_cycle23_joint_time_space_parsimonious_gof <- function(\n    input_csv = file.path(\n      "real_data",\n      "sunspots",\n      "output",\n      "sunspots_cycle23_s2_all.csv"\n    ),\n    output_dir = file.path(\n      "real_data",\n      "sunspots",\n      "output",\n      "cycle23_joint_time_space_parsimonious_gof"\n    ),\n    start_date = "1997-06-01",\n    end_date = "2006-01-01",\n    statistics = c("ks", "cvm"),\n    time_model = c("beta", "uniform_beta"),\n    hemisphere_regression = "shared",\n    B = 1000L,\n    n_cores = 8L,\n    observed_profile_n_cores = n_cores,\n    center_seed = 20260711L,\n    dequantization_seed = 20260712L,\n    derivative_mc_seed = 20260713L,\n    bootstrap_seed = 20260714L,\n    n_sample_centers = Inf,\n    derivative_mc_size = 5000L,\n    bootstrap_block_size = 25L,\n    time_quad_n = 64L,\n    control = list()) {\n  statistics <-\n    sunspots_joint_parsimonious_parse_statistics(statistics)\n  time_model <-\n    normalize_sunspots_joint_parsimonious_time_model(time_model)\n  hemisphere_regression <-\n    sunspots_time_varying_normalize_hemisphere_regression(\n      hemisphere_regression\n    )\n  B <- as.integer(B)\n  n_cores <- as.integer(n_cores)\n  observed_profile_n_cores <-\n    as.integer(observed_profile_n_cores)\n  derivative_mc_size <- as.integer(derivative_mc_size)\n  bootstrap_block_size <- as.integer(bootstrap_block_size)\n  time_quad_n <- as.integer(time_quad_n)\n\n  if (length(B) != 1L || !is.finite(B) || B < 1L) {\n    stop("`B` must be a positive integer.")\n  }\n  if (length(n_cores) != 1L ||\n      !is.finite(n_cores) ||\n      n_cores < 1L) {\n    stop("`n_cores` must be a positive integer.")\n  }\n  if (length(observed_profile_n_cores) != 1L ||\n      !is.finite(observed_profile_n_cores) ||\n      observed_profile_n_cores < 1L) {\n    stop("`observed_profile_n_cores` must be positive.")\n  }\n  if (length(derivative_mc_size) != 1L ||\n      !is.finite(derivative_mc_size) ||\n      derivative_mc_size < 10L) {\n    stop("`derivative_mc_size` must be at least 10.")\n  }\n  if (length(bootstrap_block_size) != 1L ||\n      !is.finite(bootstrap_block_size) ||\n      bootstrap_block_size < 1L) {\n    stop("`bootstrap_block_size` must be positive.")\n  }\n  if (length(time_quad_n) != 1L ||\n      !is.finite(time_quad_n) ||\n      time_quad_n < 2L) {\n    stop("`time_quad_n` must be at least 2.")\n  }\n  if (!is.infinite(n_sample_centers)) {\n    n_sample_centers <- as.integer(n_sample_centers)\n    if (!is.finite(n_sample_centers) ||\n        n_sample_centers < 1L) {\n      stop("`n_sample_centers` must be positive or Inf.")\n    }\n  }\n\n  control <- utils::modifyList(control, list(\n    time_model = time_model,\n    hemisphere_regression = hemisphere_regression\n  ))\n  profile_l_max <-\n    as.integer(control$profile_l_max %||% 100L)\n  spatial_quad_n <-\n    as.integer(control$profile_quad_n %||% 400L)\n  center_block_size <-\n    as.integer(control$center_block_size %||% 64L)\n  distance_profile_backend <- sunspots_joint_normalize_backend(\n    control$distance_profile_backend %||% "cpp"\n  )\n  effective_backend <-\n    sunspots_joint_effective_backend(distance_profile_backend)\n\n  settings <- list(\n    time_model = time_model,\n    hemisphere_regression = hemisphere_regression,\n    B = B,\n    n_cores = n_cores,\n    observed_profile_n_cores = observed_profile_n_cores,\n    start_date = start_date,\n    end_date = end_date,\n    center_seed = as.integer(center_seed),\n    dequantization_seed = as.integer(dequantization_seed),\n    derivative_mc_seed = as.integer(derivative_mc_seed),\n    bootstrap_seed = as.integer(bootstrap_seed),\n    time_quad_n = time_quad_n,\n    profile_l_max = profile_l_max,\n    spatial_quad_n = spatial_quad_n,\n    distance_profile_backend = effective_backend\n  )\n\n  total_start <- proc.time()[["elapsed"]]\n  retained <- prepare_sunspots_cycle23_joint_time_space_data(\n    input_csv = input_csv,\n    start_date = start_date,\n    end_date = end_date,\n    dequantization_seed = dequantization_seed\n  )\n  data <- sunspots_joint_validate_data(\n    as.matrix(retained[, c("x1", "x2", "x3")]),\n    retained$s\n  )\n\n  temporal_start <- proc.time()[["elapsed"]]\n  eta_hat <- fit_sunspots_joint_parsimonious_time(\n    data$s,\n    time_model = time_model,\n    control = control\n  )\n  temporal_mle_seconds <-\n    proc.time()[["elapsed"]] - temporal_start\n\n  spatial_start <- proc.time()[["elapsed"]]\n  theta_hat <- fit_sunspots_time_varying_asymmetric_mixture(\n    data$x,\n    data$s,\n    hemisphere_regression = hemisphere_regression,\n    control = control\n  )\n  spatial_mle_seconds <-\n    proc.time()[["elapsed"]] - spatial_start\n\n  fit <- fit_sunspots_cycle23_joint_time_space_parsimonious(\n    data$x,\n    data$s,\n    time_model = time_model,\n    hemisphere_regression = hemisphere_regression,\n    control = control,\n    eta_hat = eta_hat,\n    theta_hat = theta_hat\n  )\n\n  if (!sunspots_joint_parsimonious_time_fast_regular(\n    fit$eta_hat,\n    time_model = time_model,\n    control = control\n  )) {\n    stop(\n      paste(\n        "The fitted temporal model is irregular.",\n        "The fast multiplier GOF will not be forced."\n      ),\n      call. = FALSE\n    )\n  }\n\n  center_indices <- if (is.infinite(n_sample_centers) ||\n                        n_sample_centers >= nrow(data$x)) {\n    seq_len(nrow(data$x))\n  } else {\n    sunspots_joint_select_centers(\n      nrow(data$x),\n      n_sample_centers = n_sample_centers,\n      seed = center_seed\n    )\n  }\n  if (length(center_indices) != nrow(data$x)) {\n    stop(\n      paste(\n        "The optimized parsimonious runner currently requires all",\n        "sample centers. Use `n_sample_centers = Inf`."\n      )\n    )\n  }\n\n  dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n  diagnostics <-\n    plot_sunspots_cycle23_joint_time_space_parsimonious_diagnostics(\n      data,\n      fit,\n      output_dir,\n      control = control\n    )\n  retained$temporal_fitted_density <-\n    sunspots_joint_parsimonious_time_density(\n      data$s,\n      fit$eta_hat,\n      time_model = time_model,\n      control = control\n    )\n  retained$temporal_pit <- diagnostics$time_pit\n  retained$conditional_axial_pit <- diagnostics$axial_pit\n\n  utils::write.csv(\n    retained,\n    file.path(\n      output_dir,\n      "cycle23_joint_time_space_retained_data.csv"\n    ),\n    row.names = FALSE\n  )\n\n  temporal_summary <- sunspots_joint_parsimonious_time_summary(\n    fit$eta_hat,\n    time_model = time_model,\n    control = control\n  )\n  mle_row <- data.frame(\n    model = sunspots_joint_parsimonious_model_label(\n      time_model, hemisphere_regression\n    ),\n    temporal_model = temporal_summary$temporal_model,\n    hemisphere_regression = hemisphere_regression,\n    n_parameters = fit$n_parameters,\n    temporal_n_parameters =\n      temporal_summary$temporal_n_parameters,\n    temporal_uniform_weight =\n      temporal_summary$temporal_uniform_weight,\n    temporal_beta_weight =\n      temporal_summary$temporal_beta_weight,\n    temporal_alpha = temporal_summary$temporal_alpha,\n    temporal_beta = temporal_summary$temporal_beta,\n    temporal_mean = temporal_summary$temporal_mean,\n    temporal_identification_distance =\n      temporal_summary$temporal_identification_distance,\n    temporal_loglik = fit$temporal_loglik,\n    conditional_loglik = fit$conditional_loglik,\n    joint_loglik = fit$loglik,\n    aic = fit$aic,\n    bic = fit$bic,\n    a_N = theta_hat$a_N,\n    b_N = theta_hat$b_N,\n    a_S = theta_hat$a_S,\n    b_S = theta_hat$b_S,\n    c = theta_hat$c,\n    temporal_convergence = fit$eta_hat$opt$convergence,\n    spatial_convergence = theta_hat$opt$convergence,\n    temporal_boundary_weight =\n      temporal_summary$temporal_boundary_weight,\n    temporal_boundary_shape_lower =\n      temporal_summary$temporal_boundary_shape_lower,\n    temporal_boundary_shape_upper =\n      temporal_summary$temporal_boundary_shape_upper,\n    temporal_identification_failure =\n      temporal_summary$temporal_identification_failure,\n    temporal_fast_regular =\n      temporal_summary$temporal_fast_regular,\n    stringsAsFactors = FALSE\n  )\n  utils::write.csv(\n    mle_row,\n    file.path(output_dir, "cycle23_joint_time_space_mle.csv"),\n    row.names = FALSE\n  )\n  utils::write.csv(\n    fit$eta_hat$boundary_diagnostics,\n    file.path(\n      output_dir,\n      "cycle23_joint_time_space_temporal_boundary_diagnostics.csv"\n    ),\n    row.names = FALSE\n  )\n  utils::write.csv(\n    data.frame(\n      center_rank = seq_along(center_indices),\n      center_index = center_indices,\n      recorded_timestamp =\n        retained$recorded_timestamp[center_indices],\n      calendar_day = retained$calendar_day[center_indices],\n      dequantization_jitter_day =\n        retained$dequantization_jitter_day[center_indices],\n      s = data$s[center_indices],\n      x1 = data$x[center_indices, 1L],\n      x2 = data$x[center_indices, 2L],\n      x3 = data$x[center_indices, 3L]\n    ),\n    file.path(\n      output_dir, "cycle23_joint_time_space_centers.csv"\n    ),\n    row.names = FALSE\n  )\n\n  control <- utils::modifyList(control, list(\n    time_model = time_model,\n    hemisphere_regression = hemisphere_regression,\n    derivative_mc_size = derivative_mc_size,\n    derivative_mc_seed = as.integer(derivative_mc_seed),\n    fast_multiplier_vhat_rcond_tol = as.numeric(\n      control$fast_multiplier_vhat_rcond_tol %||% 1e-12\n    ),\n    distance_profile_backend = effective_backend,\n    center_block_size = center_block_size,\n    observed_profile_n_cores = observed_profile_n_cores,\n    bootstrap_block_size = bootstrap_block_size,\n    time_quad_n = time_quad_n,\n    profile_l_max = profile_l_max,\n    profile_quad_n = spatial_quad_n,\n    fast_multiplier_backend = "cpp",\n    fast_multiplier_cpp_kernel = "contiguous_double",\n    fast_multiplier_fuse_ks_cvm = TRUE,\n    fast_multiplier_cache_corrections = "auto"\n  ))\n\n  bootstrap_start <- proc.time()[["elapsed"]]\n  joint_spec <-\n    make_sunspots_joint_time_space_parsimonious_spec(\n      time_model = time_model,\n      hemisphere_regression = hemisphere_regression\n    )\n  generic_result <- multiplier_bootstrap_gof(\n    data = cbind(data$x, data$s),\n    spec = joint_spec,\n    null = list(type = "composite"),\n    statistics = statistics,\n    ks_grid = make_sample_unique_distance_ks_grid(),\n    B = B,\n    alpha = 0.05,\n    n_cores = n_cores,\n    seed = as.integer(bootstrap_seed),\n    observed_theta_hat = fit,\n    bootstrap_method = "fast_multiplier",\n    keep = list(\n      observed_process = FALSE,\n      bootstrap_statistics = TRUE,\n      bootstrap_thetas = FALSE\n    ),\n    control = control,\n    distance_profile_backend = effective_backend\n  )\n  if (!identical(\n    generic_result$diagnostics$effective_bootstrap_method,\n    "fast_multiplier"\n  )) {\n    stop(\n      sprintf(\n        paste(\n          "The fast multiplier preparation was not retained.",\n          "effective_bootstrap_method = %s."\n        ),\n        as.character(\n          generic_result$diagnostics$effective_bootstrap_method\n        )\n      ),\n      call. = FALSE\n    )\n  }\n\n  bootstrap_seconds <-\n    proc.time()[["elapsed"]] - bootstrap_start\n  bootstrap_statistics <-\n    generic_result$bootstrap$statistics\n  observed_profile_seconds <- as.numeric(\n    generic_result$diagnostics$common_observed_seconds %||%\n      NA_real_\n  )\n  fast_preparation_seconds <- as.numeric(\n    generic_result$diagnostics$fast_prep_seconds %||%\n      NA_real_\n  )\n\n  eigenvalues <- generic_result$diagnostics$Vhat_eigenvalues\n  positive_eigenvalues <- eigenvalues[\n    is.finite(eigenvalues) & eigenvalues > 0\n  ]\n  min_positive_eigenvalue <- if (\n    length(positive_eigenvalues) > 0L\n  ) {\n    min(positive_eigenvalues)\n  } else {\n    NA_real_\n  }\n  max_positive_eigenvalue <- if (\n    length(positive_eigenvalues) > 0L\n  ) {\n    max(positive_eigenvalues)\n  } else {\n    NA_real_\n  }\n\n  total_seconds <- proc.time()[["elapsed"]] - total_start\n  numerical_diagnostics <- data.frame(\n    n = nrow(data$x),\n    n_sample_centers = length(center_indices),\n    temporal_model = time_model,\n    observed_profile_n_cores = observed_profile_n_cores,\n    derivative_mc_size =\n      generic_result$diagnostics$derivative_mc_size,\n    Vhat_rcond = generic_result$diagnostics$Vhat_rcond,\n    Vhat_condition_number =\n      generic_result$diagnostics$Vhat_condition_number,\n    Vhat_min_positive_eigenvalue =\n      min_positive_eigenvalue,\n    Vhat_max_positive_eigenvalue =\n      max_positive_eigenvalue,\n    vhat_inversion_method = "solve",\n    vhat_regularization_added = 0,\n    correction_all_finite = TRUE,\n    correction_any_nonfinite = FALSE,\n    correction_nonfinite_centers = 0,\n    temporal_near_any_bound = any(\n      fit$eta_hat$boundary_diagnostics$near_any_bound\n    ),\n    temporal_min_distance_to_lower_bound = min(\n      fit$eta_hat$boundary_diagnostics$distance_to_lower\n    ),\n    temporal_min_distance_to_upper_bound = min(\n      fit$eta_hat$boundary_diagnostics$distance_to_upper\n    ),\n    temporal_identification_distance =\n      temporal_summary$temporal_identification_distance,\n    temporal_identification_failure =\n      temporal_summary$temporal_identification_failure,\n    temporal_fast_regular =\n      temporal_summary$temporal_fast_regular,\n    stringsAsFactors = FALSE\n  )\n  utils::write.csv(\n    numerical_diagnostics,\n    file.path(\n      output_dir,\n      "cycle23_joint_time_space_numerical_diagnostics.csv"\n    ),\n    row.names = FALSE\n  )\n  utils::write.csv(\n    data.frame(\n      center_rank = integer(0),\n      center_index = integer(0),\n      correction_all_finite = logical(0),\n      correction_max_abs = numeric(0),\n      stringsAsFactors = FALSE\n    ),\n    file.path(\n      output_dir,\n      "cycle23_joint_time_space_center_correction_diagnostics.csv"\n    ),\n    row.names = FALSE\n  )\n\n  observed_statistics <- c(\n    ks = as.numeric(\n      generic_result$observed$ks$statistic %||% NA_real_\n    ),\n    cvm = as.numeric(\n      generic_result$observed$cvm$statistic %||% NA_real_\n    )\n  )[statistics]\n  timing <- list(\n    temporal_mle_seconds = temporal_mle_seconds,\n    spatial_mle_seconds = spatial_mle_seconds,\n    observed_profile_seconds = observed_profile_seconds,\n    fast_preparation_seconds = fast_preparation_seconds,\n    bootstrap_seconds = bootstrap_seconds,\n    total_seconds = total_seconds\n  )\n\n  summary <- do.call(rbind, lapply(\n    statistics,\n    function(statistic_name) {\n      sunspots_joint_parsimonious_summary_row(\n        statistic_name = statistic_name,\n        bootstrap_values =\n          bootstrap_statistics[[statistic_name]],\n        observed_value =\n          observed_statistics[[statistic_name]],\n        fit = fit,\n        generic_result = generic_result,\n        data = data,\n        center_indices = center_indices,\n        settings = settings,\n        timing = timing,\n        numerical_diagnostics = numerical_diagnostics,\n        control = control\n      )\n    }\n  ))\n  utils::write.csv(\n    summary,\n    file.path(\n      output_dir,\n      "cycle23_joint_time_space_samplegof_fast_results.csv"\n    ),\n    row.names = FALSE\n  )\n  for (statistic_name in statistics) {\n    utils::write.csv(\n      data.frame(\n        replicate = seq_along(\n          bootstrap_statistics[[statistic_name]]\n        ),\n        statistic =\n          bootstrap_statistics[[statistic_name]]\n      ),\n      file.path(\n        output_dir,\n        sprintf(\n          "cycle23_joint_time_space_samplegof_fast_bootstrap_%s.csv",\n          statistic_name\n        )\n      ),\n      row.names = FALSE\n    )\n  }\n  utils::write.csv(\n    as.data.frame(timing),\n    file.path(\n      output_dir,\n      "cycle23_joint_time_space_timing.csv"\n    ),\n    row.names = FALSE\n  )\n  writeLines(\n    capture.output(sessionInfo()),\n    file.path(output_dir, "sessionInfo.txt")\n  )\n\n  invisible(list(\n    summary = summary,\n    fit = fit,\n    observed_statistics = observed_statistics,\n    bootstrap_statistics = bootstrap_statistics,\n    centers = center_indices,\n    timing = timing,\n    output_dir = output_dir\n  ))\n}\n\nparse_sunspots_joint_parsimonious_args <- function(\n    args = commandArgs(trailingOnly = TRUE)) {\n  if (length(args) == 0L) return(list())\n  out <- list()\n  integer_keys <- c(\n    "B",\n    "n_cores",\n    "observed_profile_n_cores",\n    "center_seed",\n    "dequantization_seed",\n    "derivative_mc_seed",\n    "bootstrap_seed",\n    "derivative_mc_size",\n    "bootstrap_block_size",\n    "time_quad_n"\n  )\n  character_keys <- c(\n    "input_csv",\n    "output_dir",\n    "start_date",\n    "end_date",\n    "time_model",\n    "hemisphere_regression"\n  )\n\n  for (arg in args) {\n    if (arg %in% c("--help", "-h")) {\n      cat(paste0(\n        "Options: --statistics=ks,cvm ",\n        "--time_model=beta|uniform_beta ",\n        "--hemisphere_regression=shared|asymmetric ",\n        "--B=INTEGER --n_cores=INTEGER ",\n        "--observed_profile_n_cores=INTEGER ",\n        "--n_sample_centers=all ",\n        "--derivative_mc_size=INTEGER ",\n        "--bootstrap_block_size=INTEGER ",\n        "--time_quad_n=INTEGER ",\n        "--center_seed=INTEGER ",\n        "--dequantization_seed=INTEGER ",\n        "--derivative_mc_seed=INTEGER ",\n        "--bootstrap_seed=INTEGER ",\n        "--start_date=YYYY-MM-DD ",\n        "--end_date=YYYY-MM-DD ",\n        "--output_dir=PATH\\n"\n      ))\n      quit(save = "no", status = 0L)\n    }\n\n    parts <- strsplit(\n      sub("^--", "", arg),\n      "=",\n      fixed = TRUE\n    )[[1L]]\n    if (length(parts) != 2L) {\n      stop(sprintf("Invalid option: %s", arg))\n    }\n    key <- parts[[1L]]\n    value <- parts[[2L]]\n    if (key %in% integer_keys) {\n      out[[key]] <- as.integer(value)\n    }\n    if (identical(key, "n_sample_centers")) {\n      out[[key]] <- if (\n        tolower(value) %in% c("all", "inf", "infinity")\n      ) {\n        Inf\n      } else {\n        as.integer(value)\n      }\n    }\n    if (identical(key, "statistics")) {\n      out[[key]] <- strsplit(\n        tolower(value), ",", fixed = TRUE\n      )[[1L]]\n    }\n    if (key %in% character_keys) out[[key]] <- value\n  }\n  out\n}\n\nif (sys.nframe() == 0L) {\n  do.call(\n    run_sunspots_cycle23_joint_time_space_parsimonious_gof,\n    parse_sunspots_joint_parsimonious_args()\n  )\n}\n',
    Path('tests/testthat/test_sunspots_joint_parsimonious_time_models.R'): 'library(testthat)\n\noldwd <- setwd(normalizePath(file.path("..", "..")))\non.exit(setwd(oldwd), add = TRUE)\n\nsource(file.path(\n  "real_data",\n  "sunspots",\n  "sunspots_cycle23_joint_time_space.R"\n))\nsource(file.path(\n  "real_data",\n  "sunspots",\n  "sunspots_cycle23_joint_time_models_parsimonious.R"\n))\nsource(file.path(\n  "bootstrap",\n  "sunspots_joint_time_space_parsimonious_model_spec.R"\n))\n\nparsimonious_test_theta <- function(shared = TRUE) {\n  if (isTRUE(shared)) {\n    return(list(\n      a_N = 0.48,\n      b_N = -0.2,\n      a_S = 0.48,\n      b_S = -0.2,\n      c = 18,\n      n_parameters = 3L\n    ))\n  }\n  list(\n    a_N = 0.52,\n    b_N = -0.22,\n    a_S = 0.45,\n    b_S = -0.16,\n    c = 18,\n    n_parameters = 5L\n  )\n}\n\nparsimonious_test_eta <- function(time_model) {\n  if (identical(time_model, "beta")) {\n    return(sunspots_joint_parsimonious_time_validate_eta(\n      list(\n        time_model = "beta",\n        alpha = 3.2,\n        beta = 5.4\n      ),\n      time_model = "beta"\n    ))\n  }\n  sunspots_joint_parsimonious_time_validate_eta(\n    list(\n      time_model = "uniform_beta",\n      beta_weight = 0.62,\n      alpha = 3.2,\n      beta = 5.4\n    ),\n    time_model = "uniform_beta"\n  )\n}\n\ntest_that("parsimonious temporal densities, CDFs, and quadratures are valid", {\n  for (time_model in c("beta", "uniform_beta")) {\n    eta <- parsimonious_test_eta(time_model)\n    integral <- integrate(\n      function(s) {\n        sunspots_joint_parsimonious_time_density(\n          s,\n          eta,\n          time_model = time_model\n        )\n      },\n      lower = 0,\n      upper = 1,\n      subdivisions = 2000L,\n      rel.tol = 1e-10\n    )$value\n    expect_equal(integral, 1, tolerance = 1e-9)\n\n    expect_equal(\n      sunspots_joint_parsimonious_time_cdf(\n        c(-1, 0, 1, 2),\n        eta,\n        time_model = time_model\n      ),\n      c(0, 0, 1, 1),\n      tolerance = 1e-14\n    )\n\n    quadrature <- sunspots_joint_parsimonious_time_quadrature(\n      eta,\n      n_nodes = 64L,\n      time_model = time_model\n    )\n    expect_equal(sum(quadrature$weights), 1, tolerance = 1e-12)\n    expect_lt(quadrature$mass_error, 1e-12)\n\n    high_precision <- integrate(\n      function(s) {\n        exp(s) *\n          sunspots_joint_parsimonious_time_density(\n            s,\n            eta,\n            time_model = time_model\n          )\n      },\n      lower = 0,\n      upper = 1,\n      subdivisions = 2000L,\n      rel.tol = 1e-11\n    )$value\n    expect_equal(\n      sum(quadrature$weights * exp(quadrature$nodes)),\n      high_precision,\n      tolerance = 1e-10\n    )\n  }\n})\n\ntest_that("parsimonious temporal pack and unpack are inverse operations", {\n  for (time_model in c("beta", "uniform_beta")) {\n    eta <- parsimonious_test_eta(time_model)\n    par <- sunspots_joint_parsimonious_time_pack_eta(\n      eta,\n      time_model = time_model\n    )\n    recovered <- sunspots_joint_parsimonious_time_unpack_eta(\n      par,\n      time_model = time_model\n    )\n    expect_equal(recovered$alpha, eta$alpha, tolerance = 1e-14)\n    expect_equal(recovered$beta, eta$beta, tolerance = 1e-14)\n    expect_equal(\n      recovered$beta_weight,\n      eta$beta_weight,\n      tolerance = 1e-14\n    )\n  }\n})\n\ntest_that("analytic parsimonious temporal scores match finite differences", {\n  set.seed(20260806)\n  for (time_model in c("beta", "uniform_beta")) {\n    eta <- parsimonious_test_eta(time_model)\n    s <- sample_sunspots_joint_parsimonious_time(\n      80L,\n      eta,\n      time_model = time_model\n    )\n    par <- sunspots_joint_parsimonious_time_pack_eta(\n      eta,\n      time_model = time_model\n    )\n    analytic <- sunspots_joint_parsimonious_time_score_matrix(\n      s,\n      par,\n      time_model = time_model\n    )\n    step <- 1e-6\n    numeric <- vapply(seq_along(par), function(index) {\n      plus <- par\n      minus <- par\n      plus[[index]] <- plus[[index]] + step\n      minus[[index]] <- minus[[index]] - step\n      plus_eta <- sunspots_joint_parsimonious_time_unpack_eta(\n        plus,\n        time_model = time_model\n      )\n      minus_eta <- sunspots_joint_parsimonious_time_unpack_eta(\n        minus,\n        time_model = time_model\n      )\n      (\n        sunspots_joint_parsimonious_time_log_density(\n          s,\n          plus_eta,\n          time_model = time_model\n        ) -\n          sunspots_joint_parsimonious_time_log_density(\n            s,\n            minus_eta,\n            time_model = time_model\n          )\n      ) / (2 * step)\n    }, numeric(length(s)))\n    expect_equal(\n      as.numeric(analytic),\n      as.numeric(numeric),\n      tolerance = 2e-5\n    )\n  }\n})\n\ntest_that("parsimonious temporal scores have approximately zero mean", {\n  set.seed(20260807)\n  for (time_model in c("beta", "uniform_beta")) {\n    eta <- parsimonious_test_eta(time_model)\n    s <- sample_sunspots_joint_parsimonious_time(\n      30000L,\n      eta,\n      time_model = time_model\n    )\n    par <- sunspots_joint_parsimonious_time_pack_eta(\n      eta,\n      time_model = time_model\n    )\n    score <- sunspots_joint_parsimonious_time_score_matrix(\n      s,\n      par,\n      time_model = time_model\n    )\n    expect_true(all(abs(colMeans(score)) < 0.035))\n  }\n})\n\ntest_that("parsimonious temporal MLEs are finite on simulated samples", {\n  set.seed(20260808)\n  for (time_model in c("beta", "uniform_beta")) {\n    eta <- parsimonious_test_eta(time_model)\n    s <- sample_sunspots_joint_parsimonious_time(\n      1000L,\n      eta,\n      time_model = time_model\n    )\n    fit <- suppressWarnings(\n      fit_sunspots_joint_parsimonious_time(\n        s,\n        time_model = time_model,\n        control = list(\n          parsimonious_time_n_starts =\n            if (identical(time_model, "beta")) 3L else 6L,\n          parsimonious_time_nelder_mead_control =\n            list(maxit = 1500L, reltol = 1e-9)\n        )\n      )\n    )\n    expect_true(is.finite(fit$loglik))\n    expect_gt(fit$alpha, 0)\n    expect_gt(fit$beta, 0)\n    expect_gte(fit$n_successful_starts, 1L)\n    expect_equal(fit$n_parameters, if (\n      identical(time_model, "beta")\n    ) 2L else 3L)\n  }\n})\n\ntest_that("uniform-beta nonidentification and mixture boundaries are detected", {\n  unidentified <- list(\n    time_model = "uniform_beta",\n    beta_weight = 0.5,\n    alpha = 1,\n    beta = 1\n  )\n  flags <- sunspots_joint_parsimonious_time_boundary_flags(\n    unidentified,\n    time_model = "uniform_beta"\n  )\n  expect_true(flags$identification)\n  expect_false(\n    sunspots_joint_parsimonious_time_fast_regular(\n      unidentified,\n      time_model = "uniform_beta"\n    )\n  )\n\n  bounds <- sunspots_joint_parsimonious_time_control()\n  boundary <- list(\n    time_model = "uniform_beta",\n    beta_weight = bounds$weight_eps,\n    alpha = 2,\n    beta = 3\n  )\n  flags <- sunspots_joint_parsimonious_time_boundary_flags(\n    boundary,\n    time_model = "uniform_beta"\n  )\n  expect_true(flags$weight)\n  expect_false(\n    sunspots_joint_parsimonious_time_fast_regular(\n      boundary,\n      time_model = "uniform_beta"\n    )\n  )\n})\n\ntest_that("parsimonious joint scores have the expected dimensions", {\n  for (time_model in c("beta", "uniform_beta")) {\n    for (shared in c(TRUE, FALSE)) {\n      eta <- parsimonious_test_eta(time_model)\n      fit <- list(\n        time_model = time_model,\n        eta_hat = eta,\n        theta_hat = parsimonious_test_theta(shared)\n      )\n      control <- list(\n        time_model = time_model,\n        hemisphere_regression = if (shared) "shared" else "asymmetric"\n      )\n      par <- sunspots_joint_parsimonious_pack_par(fit, control)\n      set.seed(if (shared) 20260809 else 20260810)\n      sample <- sample_sunspots_joint_time_space_parsimonious(\n        35L,\n        par,\n        control\n      )\n      score <- sunspots_joint_parsimonious_score_matrix(\n        sample,\n        par,\n        control\n      )\n      expected <- sunspots_joint_parsimonious_time_n_parameters(\n        time_model\n      ) + if (shared) 3L else 5L\n      expect_identical(dim(score), c(35L, expected))\n      expect_true(all(is.finite(score)))\n    }\n  }\n})\n\ntest_that("parsimonious temporal profiles agree between R and C++", {\n  skip_if_not_installed("Rcpp")\n  theta <- parsimonious_test_theta(TRUE)\n  set.seed(20260811)\n  radii <- matrix(runif(42L), nrow = 6L)\n  rho <- runif(6L, -1, 1)\n  center_s <- runif(6L)\n\n  for (time_model in c("beta", "uniform_beta")) {\n    eta <- parsimonious_test_eta(time_model)\n    quadrature <- sunspots_joint_parsimonious_time_quadrature(\n      eta,\n      n_nodes = 18L,\n      time_model = time_model\n    )\n    coefficients <- sunspots_joint_conditional_legendre_coefficients(\n      theta,\n      quadrature$nodes,\n      l_max = 40L,\n      quad_n = 180L\n    )\n    reference <- sunspots_joint_profile_block(\n      radii,\n      rho,\n      center_s,\n      quadrature$nodes,\n      quadrature$weights,\n      coefficients,\n      backend = "r"\n    )\n    compiled <- sunspots_joint_profile_block(\n      radii,\n      rho,\n      center_s,\n      quadrature$nodes,\n      quadrature$weights,\n      coefficients,\n      backend = "cpp"\n    )\n    expect_equal(compiled, reference, tolerance = 1e-12)\n  }\n})\n\ntest_that("parsimonious joint spec names are certified for C++", {\n  expected <- c(\n    "sunspots_joint_time_space_beta_shared",\n    "sunspots_joint_time_space_beta_asymmetric",\n    "sunspots_joint_time_space_uniform_beta_shared",\n    "sunspots_joint_time_space_uniform_beta_asymmetric"\n  )\n  expect_true(all(vapply(\n    expected,\n    distance_profile_cpp_supports_spec,\n    logical(1L)\n  )))\n\n  expect_identical(\n    make_sunspots_joint_time_space_parsimonious_spec(\n      "beta", "shared"\n    )$name,\n    expected[[1L]]\n  )\n  expect_identical(\n    make_sunspots_joint_time_space_parsimonious_spec(\n      "uniform_beta", "asymmetric"\n    )$name,\n    expected[[4L]]\n  )\n})\n',
}


REGISTRY_PATH = Path("distance_profile_backend.R")
REGISTRY_OLD = (
    '      grepl("^sunspots_joint_time_space_(asymmetric|shared)$", spec_name)\n'
)
REGISTRY_NEW = (
    '      grepl("^sunspots_joint_time_space_(asymmetric|shared)$", spec_name) ||\n'
    '      grepl(\n'
    '        "^sunspots_joint_time_space_(beta|uniform_beta)_(asymmetric|shared)$",\n'
    '        spec_name\n'
    '      )\n'
)


def run(*args: str, capture: bool = False) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        list(args),
        check=True,
        text=True,
        capture_output=capture,
    )


def fail(message: str) -> None:
    raise SystemExit(message)


def main() -> None:
    root = Path.cwd()
    if not (root / ".git").exists():
        fail("Run this script from the repository root.")

    head = run("git", "rev-parse", "HEAD", capture=True).stdout.strip()
    if head != EXPECTED_HEAD:
        fail(
            "Unexpected HEAD.\n"
            f"Expected: {EXPECTED_HEAD}\n"
            f"Found:    {head}\n"
            "No files were changed."
        )

    status = run("git", "status", "--porcelain", capture=True).stdout
    if status.strip():
        fail(
            "The Git tree is not clean. Commit, stash, or discard changes first.\n"
            "No files were changed."
        )

    existing = [str(path) for path in NEW_FILES if path.exists()]
    if existing:
        fail(
            "Refusing to overwrite files that already exist:\n- "
            + "\n- ".join(existing)
        )

    registry = REGISTRY_PATH.read_text(encoding="utf-8")
    if registry.count(REGISTRY_OLD) != 1:
        fail(
            "The expected C++ registry block was not found exactly once.\n"
            "No files were changed."
        )

    created: list[Path] = []
    try:
        for path, content in NEW_FILES.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content.rstrip() + "\n", encoding="utf-8")
            created.append(path)

        REGISTRY_PATH.write_text(
            registry.replace(REGISTRY_OLD, REGISTRY_NEW),
            encoding="utf-8",
        )

        run("git", "diff", "--check")

        rscript = shutil.which("Rscript")
        if rscript:
            for path in NEW_FILES:
                expression = (
                    f"parse(file={str(path)!r}); "
                    f"cat('Parsed: {str(path)}\\n')"
                )
                run(rscript, "-e", expression)
        else:
            print("Rscript was not found; R syntax parsing was skipped.")

    except Exception:
        REGISTRY_PATH.write_text(registry, encoding="utf-8")
        for path in reversed(created):
            path.unlink(missing_ok=True)
        raise

    print("\nPatch applied successfully.")
    print("No commit or push was performed.")
    print("\nCreated:")
    for path in NEW_FILES:
        print(f"  {path}")
    print(f"Modified:\n  {REGISTRY_PATH}")
    print("\nNext commands:")
    print(
        "  Rscript -e 'testthat::test_file("
        '"tests/testthat/test_sunspots_joint_parsimonious_time_models.R")'
        "'"
    )
    print(
        "  Rscript -e 'testthat::test_file("
        '"tests/testthat/test_sunspots_joint_sorted_cpp_parallel.R")'
        "'"
    )
    print(
        "  Rscript -e 'testthat::test_file("
        '"tests/testthat/test_sunspots_joint_generic_spec_fast.R")'
        "'"
    )
    print("  git diff --check")
    print("  git status --short")
    print("  git diff --stat")


if __name__ == "__main__":
    main()
